import React, { useCallback, useEffect, useState } from "react";

import makeStyles from "@mui/styles/makeStyles";
import Button from "@mui/material/Button";
import Chip from "@mui/material/Chip";
import CircularProgress from "@mui/material/CircularProgress";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableCell from "@mui/material/TableCell";
import TableHead from "@mui/material/TableHead";
import TableRow from "@mui/material/TableRow";
import Tooltip from "@mui/material/Tooltip";
import Typography from "@mui/material/Typography";
import FiberManualRecordIcon from "@mui/icons-material/FiberManualRecord";
import PeopleAltOutlinedIcon from "@mui/icons-material/PeopleAltOutlined";
import EditIcon from "@mui/icons-material/Edit";
import PersonAddAltIcon from "@mui/icons-material/PersonAddAlt1";

import api from "../../services/api";
import toastError from "../../errors/toastError";
import EmptyState from "../../components/EmptyState";
import { i18n } from "../../translate/i18n";

const useStyles = makeStyles((theme) => ({
  cabecalho: {
    display: "flex",
    alignItems: "flex-start",
    justifyContent: "space-between",
    flexWrap: "wrap",
    gap: theme.spacing(2),
    marginBottom: theme.spacing(2),
  },

  explicacao: {
    maxWidth: 620,
    color: theme.palette.text.secondary,
  },

  carregando: {
    display: "flex",
    justifyContent: "center",
    padding: theme.spacing(6),
  },

  tabela: { minWidth: 640 },
}));

/**
 * Quem usa o sistema nesta empresa.
 *
 * Lista e leva — não edita. Criar, alterar e excluir usuário acontece dentro
 * da empresa, na tela de Usuários que o admin dela já usa: são as mesmas
 * regras de perfil, setor, limite e permissão individual, e uma segunda cópia
 * do formulário aqui significaria manter duas versões da mesma validação.
 *
 * O botão de cada linha entra na empresa e cai direto em /users, então o
 * caminho custa um clique a mais que editar aqui — e nenhuma tela a mais para
 * manter.
 */
const AbaUsuarios = ({ company, onEntrar }) => {
  const classes = useStyles();
  const [users, setUsers] = useState([]);
  const [carregando, setCarregando] = useState(true);

  const carregar = useCallback(async () => {
    try {
      const { data } = await api.get(`/companies/${company.id}/users`);
      setUsers(Array.isArray(data) ? data : []);
    } catch (err) {
      toastError(err);
    } finally {
      setCarregando(false);
    }
  }, [company.id]);

  useEffect(() => {
    carregar();
  }, [carregar]);

  if (carregando) {
    return (
      <div className={classes.carregando}>
        <CircularProgress />
      </div>
    );
  }

  const administradores = users.filter((u) => u.profile === "admin").length;

  return (
    <>
      <div className={classes.cabecalho}>
        <div className={classes.explicacao}>
          <Typography variant="body2">
            {users.length} usuário(s), {administradores} administrador(es).
          </Typography>
          <Typography variant="caption">
            Criar e editar usuário acontece dentro da empresa, na tela de
            Usuários — as mesmas regras de perfil, setor e permissão.
          </Typography>
        </div>

        <Button
          variant="contained"
          color="primary"
          startIcon={<PersonAddAltIcon />}
          onClick={() => onEntrar(company, "/users")}
        >
          Gerenciar usuários
        </Button>
      </div>

      {users.length === 0 ? (
        <EmptyState
          icon={PeopleAltOutlinedIcon}
          title="Nenhum usuário nesta empresa"
          description="Uma empresa sem usuário não tem como ser acessada. Entre nela e crie ao menos o administrador."
          action={
            <Button
              variant="contained"
              color="primary"
              startIcon={<PersonAddAltIcon />}
              onClick={() => onEntrar(company, "/users")}
            >
              Criar o primeiro usuário
            </Button>
          }
        />
      ) : (
        <Table size="small" className={classes.tabela}>
          <TableHead>
            <TableRow>
              <TableCell align="center">Status</TableCell>
              <TableCell>Nome</TableCell>
              <TableCell>E-mail</TableCell>
              <TableCell>Tipo de conta</TableCell>
              <TableCell>Setores</TableCell>
              <TableCell align="center">Ações</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {users.map((user) => (
              <TableRow key={user.id}>
                <TableCell align="center">
                  <Tooltip
                    arrow
                    title={
                      user.online
                        ? i18n.t("users.table.online")
                        : i18n.t("users.table.offline")
                    }
                  >
                    <FiberManualRecordIcon
                      fontSize="small"
                      color={user.online ? "success" : "disabled"}
                      style={{ verticalAlign: "middle" }}
                    />
                  </Tooltip>
                </TableCell>
                <TableCell>{user.name}</TableCell>
                <TableCell>{user.email}</TableCell>
                <TableCell>
                  {i18n.t(`users.profiles.${user.profile}`, {
                    defaultValue: user.profile,
                  })}
                </TableCell>
                <TableCell>
                  {user.queues?.length
                    ? user.queues.map((q) => (
                        <Chip
                          key={q.id}
                          size="small"
                          variant="outlined"
                          label={q.name}
                          style={{ marginRight: 4 }}
                        />
                      ))
                    : "—"}
                </TableCell>
                <TableCell align="center">
                  <Tooltip title="Entrar na empresa para editar" arrow>
                    <Button
                      size="small"
                      startIcon={<EditIcon />}
                      onClick={() => onEntrar(company, "/users")}
                    >
                      Editar
                    </Button>
                  </Tooltip>
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      )}
    </>
  );
};

export default AbaUsuarios;
