import React, { useState, useEffect, useReducer } from "react";
import openSocket from "../../services/socket-io";
import { toast } from "react-toastify";

import makeStyles from '@mui/styles/makeStyles';
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableCell from "@mui/material/TableCell";
import TableHead from "@mui/material/TableHead";
import TableRow from "@mui/material/TableRow";
import Paper from "@mui/material/Paper";
import Button from "@mui/material/Button";
import Chip from "@mui/material/Chip";

import IconButton from "@mui/material/IconButton";
import DeleteOutlineIcon from "@mui/icons-material/DeleteOutline";
import EditIcon from "@mui/icons-material/Edit";

import api from "../../services/api";
import TableRowSkeleton from "../../components/TableRowSkeleton";
import TableEmpty from "../../components/EmptyState/TableEmpty";
import SearchField from "../../components/SearchField";
import Tooltip from "@mui/material/Tooltip";
import AddIcon from "@mui/icons-material/Add";
import GroupWorkOutlinedIcon from "@mui/icons-material/GroupWorkOutlined";
import SearchOffIcon from "@mui/icons-material/SearchOff";
import CustomerModal from "../../components/CustomerModal";
import ConfirmationModal from "../../components/ConfirmationModal/";

import { i18n } from "../../translate/i18n";
import MainHeader from "../../components/MainHeader";
import Title from "../../components/Title";
import MainHeaderButtonsWrapper from "../../components/MainHeaderButtonsWrapper";
import MainContainer from "../../components/MainContainer";
import toastError from "../../errors/toastError";
import { Can } from "../../components/Can";

const reducer = (state, action) => {
  if (action.type === "LOAD_CUSTOMERS") {
    const customers = action.payload;
    const newCustomers = [];

    customers.forEach((customer) => {
      const customerIndex = state.findIndex((c) => c.id === customer.id);
      if (customerIndex !== -1) {
        state[customerIndex] = customer;
      } else {
        newCustomers.push(customer);
      }
    });

    return [...state, ...newCustomers];
  }

  if (action.type === "UPDATE_CUSTOMERS") {
    const customer = action.payload;
    const customerIndex = state.findIndex((c) => c.id === customer.id);

    if (customerIndex !== -1) {
      state[customerIndex] = customer;
      return [...state];
    } else {
      return [customer, ...state];
    }
  }

  if (action.type === "DELETE_CUSTOMER") {
    const customerId = action.payload;

    const customerIndex = state.findIndex((c) => c.id === customerId);
    if (customerIndex !== -1) {
      state.splice(customerIndex, 1);
    }
    return [...state];
  }

  if (action.type === "RESET") {
    return [];
  }
};

const useStyles = makeStyles((theme) => ({
  /**
   * Painel de conteúdo das telas de listagem.
   *
   * Ganhou borda e margem: o Paper deixou de ter sombra no tema novo, e sem
   * nenhuma das duas a tabela ficava solta no meio da página, encostada nas
   * bordas da janela sem nada dizendo onde ela começa.
   */
  mainPaper: {
    flex: 1,
    margin: theme.spacing(0, 2, 2),
    padding: theme.spacing(0.5),
    // "auto" e não "scroll": a barra vazia desenhava uma faixa cinza fixa na
    // direita de toda listagem, inclusive nas que cabem na tela.
    overflowY: "auto",
    // Sem isto a tabela larga estoura o painel e rola a página inteira.
    overflowX: "auto",
    border: `1px solid ${theme.palette.divider}`,
    ...theme.scrollbarStyles,
  },
}));

const statusColors = {
  lead: "default",
  active: "primary",
  inactive: "secondary",
};

const Customers = () => {
  const classes = useStyles();

  const [loading, setLoading] = useState(false);
  const [pageNumber, setPageNumber] = useState(1);
  const [searchParam, setSearchParam] = useState("");
  const [customers, dispatch] = useReducer(reducer, []);
  const [selectedCustomerId, setSelectedCustomerId] = useState(null);
  const [customerModalOpen, setCustomerModalOpen] = useState(false);
  const [deletingCustomer, setDeletingCustomer] = useState(null);
  const [confirmOpen, setConfirmOpen] = useState(false);
  const [hasMore, setHasMore] = useState(false);

  useEffect(() => {
    dispatch({ type: "RESET" });
    setPageNumber(1);
  }, [searchParam]);

  useEffect(() => {
    setLoading(true);
    const delayDebounceFn = setTimeout(() => {
      const fetchCustomers = async () => {
        try {
          const { data } = await api.get("/customers", {
            params: { searchParam, pageNumber },
          });
          dispatch({ type: "LOAD_CUSTOMERS", payload: data.customers });
          setHasMore(data.hasMore);
          setLoading(false);
        } catch (err) {
          toastError(err);
        }
      };
      fetchCustomers();
    }, 500);
    return () => clearTimeout(delayDebounceFn);
  }, [searchParam, pageNumber]);

  useEffect(() => {
    const socket = openSocket();

    socket.on("customer", (data) => {
      if (data.action === "update" || data.action === "create") {
        dispatch({ type: "UPDATE_CUSTOMERS", payload: data.customer });
      }

      if (data.action === "delete") {
        dispatch({ type: "DELETE_CUSTOMER", payload: +data.customerId });
      }
    });

    return () => {
      socket.disconnect();
    };
  }, []);

  const handleSearch = (event) => {
    setSearchParam(event.target.value.toLowerCase());
  };

  const handleOpenCustomerModal = () => {
    setSelectedCustomerId(null);
    setCustomerModalOpen(true);
  };

  const handleCloseCustomerModal = () => {
    setSelectedCustomerId(null);
    setCustomerModalOpen(false);
  };

  const handleEditCustomer = (customerId) => {
    setSelectedCustomerId(customerId);
    setCustomerModalOpen(true);
  };

  const handleDeleteCustomer = async (customerId) => {
    try {
      await api.delete(`/customers/${customerId}`);
      toast.success(i18n.t("customers.toasts.deleted"));
    } catch (err) {
      toastError(err);
    }
    setDeletingCustomer(null);
    setSearchParam("");
    setPageNumber(1);
  };

  const loadMore = () => {
    setPageNumber((prevState) => prevState + 1);
  };

  const handleScroll = (e) => {
    if (!hasMore || loading) return;
    const { scrollTop, scrollHeight, clientHeight } = e.currentTarget;
    if (scrollHeight - (scrollTop + 100) < clientHeight) {
      loadMore();
    }
  };

  return (
    <MainContainer className={classes.mainContainer}>
      <CustomerModal
        open={customerModalOpen}
        onClose={handleCloseCustomerModal}
        aria-labelledby="form-dialog-title"
        customerId={selectedCustomerId}
      ></CustomerModal>
      <ConfirmationModal
        title={
          deletingCustomer
            ? `${i18n.t("customers.confirmationModal.deleteTitle")} ${
                deletingCustomer.name
              }?`
            : ""
        }
        open={confirmOpen}
        onClose={setConfirmOpen}
        danger
        confirmLabel={i18n.t("customers.confirmationModal.confirmDelete")}
        onConfirm={() =>
          deletingCustomer && handleDeleteCustomer(deletingCustomer.id)
        }
      >
        {i18n.t("customers.confirmationModal.deleteMessage")}
      </ConfirmationModal>
      <MainHeader>
        <Title>{i18n.t("customers.title")}</Title>
        <MainHeaderButtonsWrapper>
          <SearchField
            value={searchParam}
            onChange={handleSearch}
            onClear={() => setSearchParam("")}
            placeholder={i18n.t("customers.searchPlaceholder")}
          />
          <Can permission="clients:create">
            <Button
              variant="contained"
              color="primary"
              startIcon={<AddIcon />}
              onClick={handleOpenCustomerModal}
            >
              {i18n.t("customers.buttons.add")}
            </Button>
          </Can>
        </MainHeaderButtonsWrapper>
      </MainHeader>
      <Paper
        className={classes.mainPaper}
        variant="outlined"
        onScroll={handleScroll}
      >
        <Table size="small">
          <TableHead>
            <TableRow>
              <TableCell>{i18n.t("customers.table.name")}</TableCell>
              <TableCell>{i18n.t("customers.table.document")}</TableCell>
              <TableCell>{i18n.t("customers.table.phone")}</TableCell>
              <TableCell>{i18n.t("customers.table.segment")}</TableCell>
              <TableCell align="center">
                {i18n.t("customers.table.status")}
              </TableCell>
              <TableCell align="center">
                {i18n.t("customers.table.actions")}
              </TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            <>
              {customers.map((customer) => (
                <TableRow key={customer.id}>
                  <TableCell>
                    {customer.tradeName || customer.name}
                  </TableCell>
                  <TableCell>{customer.document}</TableCell>
                  <TableCell>
                    {customer.whatsapp || customer.phone}
                  </TableCell>
                  <TableCell>{customer.segment}</TableCell>
                  <TableCell align="center">
                    <Chip
                      size="small"
                      label={i18n.t(`customers.status.${customer.status}`)}
                      color={statusColors[customer.status] || "default"}
                    />
                  </TableCell>
                  <TableCell align="center">
                    <Can permission="clients:edit">
                      <Tooltip title={i18n.t("customers.actions.edit")} arrow>
                        <IconButton
                          size="small"
                          aria-label={i18n.t("customers.actions.edit")}
                          onClick={() => handleEditCustomer(customer.id)}
                        >
                          <EditIcon />
                        </IconButton>
                      </Tooltip>
                    </Can>
                    <Can permission="clients:delete">
                      <Tooltip title={i18n.t("customers.actions.delete")} arrow>
                        <IconButton
                          size="small"
                          aria-label={i18n.t("customers.actions.delete")}
                          onClick={() => {
                            setConfirmOpen(true);
                            setDeletingCustomer(customer);
                          }}
                        >
                          <DeleteOutlineIcon />
                        </IconButton>
                      </Tooltip>
                    </Can>
                  </TableCell>
                </TableRow>
              ))}
              {!loading && customers.length === 0 && (
                <TableEmpty
                  colSpan={6}
                  icon={searchParam ? SearchOffIcon : GroupWorkOutlinedIcon}
                  title={
                    searchParam
                      ? i18n.t("customers.empty.searchTitle")
                      : i18n.t("customers.empty.title")
                  }
                  description={
                    searchParam
                      ? i18n.t("customers.empty.searchMessage")
                      : i18n.t("customers.empty.message")
                  }
                  action={
                    !searchParam && (
                      <Can permission="clients:create">
                        <Button
                          variant="contained"
                          color="primary"
                          startIcon={<AddIcon />}
                          onClick={handleOpenCustomerModal}
                        >
                          {i18n.t("customers.buttons.add")}
                        </Button>
                      </Can>
                    )
                  }
                />
              )}
              {loading && <TableRowSkeleton columns={6} />}
            </>
          </TableBody>
        </Table>
      </Paper>
    </MainContainer>
  );
};

export default Customers;
